import boto3
import botocore.exceptions
import pytest
from moto import mock_route53

ZONE = 'cname.local'
FQDN = f"test.{ZONE}"
FQDN_TARGET = "develop.domain.com"


@pytest.fixture
def route53_client():
    with mock_route53():
        yield boto3.client("route53")


@pytest.fixture
def route53_zone(route53_client):
    resp = route53_client.create_hosted_zone(
        Name=ZONE,
        CallerReference='ref',
        DelegationSetId='string'
    )
    return resp['HostedZone']['Id']


def create_cname(route53_client, zone_id):
    return route53_client.change_resource_record_sets(
        HostedZoneId=zone_id,
        ChangeBatch={
            "Changes": [
                {
                    "Action": "CREATE",
                    "ResourceRecordSet": {
                        "Name": FQDN,
                        "Type": "CNAME",
                        "TTL": 600,
                        "ResourceRecords": [
                            {"Value": FQDN_TARGET},
                        ],
                    },
                },
            ]
        },
    )


def test_create_duplicate_record_fails(route53_client, route53_zone):
    zone_id = route53_zone
    # First creation should succeed
    first_response = create_cname(route53_client, zone_id)
    assert 'ChangeInfo' in first_response

    # Second creation should raise an error
    with pytest.raises(botocore.exceptions.ClientError):
        create_cname(route53_client, zone_id)

", "security_risk": "MEDIUM"}

