from moto.core.models import BaseBackend, BaseModel


class ResilienceHubBackend(BaseBackend):
    def __init__(self, region_name):
        super().__init__(region_name=region_name)
        self.policies = {}

    def create_resiliency_policy(self, policy_name, policy_description, policy, tier):
